import React, { useState, useEffect } from "react";

const Settings = () => {
  // ============================================================
  // GOOGLE
  // ============================================================

  const [googleConnected, setGoogleConnected] = useState(() => {
    try {
      const val = localStorage.getItem("googleConnected");
      return val !== null ? JSON.parse(val) : false;
    } catch {
      return false;
    }
  });

  // ============================================================
  // GOOGLE CALENDAR SELECTION
  // ============================================================

  const [calendars, setCalendars] = useState([]);
  const [selectedCalendar, setSelectedCalendar] = useState(null); // Default to null (no selection)
  const [calendarLoading, setCalendarLoading] = useState(false);
  const [calendarError, setCalendarError] = useState(null);
  const [calendarSuccess, setCalendarSuccess] = useState(false);

  // ============================================================
  // OBSIDIAN
  // ============================================================

  const [obsidianPath, setObsidianPath] = useState("");

  // ============================================================
  // GENERAL
  // ============================================================

  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  // ============================================================
  // TELEGRAM
  // ============================================================

  const [telegramLinked, setTelegramLinked] = useState(false);
  const [telegramId, setTelegramId] = useState(null);
  const [telegramLinkedAt, setTelegramLinkedAt] = useState(null);

  const [telegramCode, setTelegramCode] = useState("");
  const [telegramCodeExpiresAt, setTelegramCodeExpiresAt] = useState(null);

  const [telegramLoading, setTelegramLoading] = useState(false);
  const [telegramError, setTelegramError] = useState(null);
  const [telegramMessage, setTelegramMessage] = useState(null);

  // ============================================================
  // GOOGLE STATUS
  // ============================================================

  useEffect(() => {
    const checkStatus = async () => {
      setLoading(true);
      setError(null);

      try {
        const response = await fetch("/api/google/status", {
          credentials: "include",
        });

        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }

        const data = await response.json();

        setGoogleConnected(data.connected || false);

        localStorage.setItem(
          "googleConnected",
          JSON.stringify(data.connected || false)
        );
      } catch (err) {
        console.error("Failed to check Google status:", err);
        setError("Не удалось проверить статус подключения к Google");
      } finally {
        setLoading(false);
      }
    };

    checkStatus();
  }, []);

  // ============================================================
  // GOOGLE CALENDARS FETCH
  // ============================================================

  useEffect(() => {
    const fetchCalendars = async () => {
      if (!googleConnected) {
        // If Google is not connected, reset to default
        setCalendars([{ id: "primary", summary: "Основной календарь" }]);
        setSelectedCalendar(null);
        return;
      }

      setCalendarLoading(true);
      setCalendarError(null);
      setCalendarSuccess(false);

      try {
        const response = await fetch("/api/google/calendars", {
          credentials: "include",
        });

        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }

        const data = await response.json();

        setCalendars(data.calendars || [{ id: "primary", summary: "Основной календарь" }]);
        // If we don't have a selected calendar yet, keep it as null (no selection)
        // User must explicitly select a calendar
      } catch (err) {
        console.error("Failed to fetch Google calendars:", err);
        setCalendarError("Не удалось загрузить список календарей");
        // Fallback to primary calendar
        setCalendars([{ id: "primary", summary: "Основной календарь" }]);
        setSelectedCalendar(null);
      } finally {
        setCalendarLoading(false);
      }
    };

    // Fetch calendars when googleConnected changes
    fetchCalendars();
  }, [googleConnected]);

  // ============================================================
  // OBSIDIAN PATH
  // ============================================================

  useEffect(() => {
    const loadObsidianPath = async () => {
      try {
        const response = await fetch("/api/obsidian/path", {
          credentials: "include",
        });

        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }

        const data = await response.json();
        const path = data.path || "";

        setObsidianPath(path);

        if (path) {
          localStorage.setItem("obsidianPath", path);
        }
      } catch (err) {
        console.error("Failed to load Obsidian path:", err);

        try {
          const val = localStorage.getItem("obsidianPath");

          if (val !== null) {
            setObsidianPath(val);
          }
        } catch (e) {
          console.error(
            "Failed to read Obsidian path from localStorage:",
            e
          );
        }
      }
    };

    loadObsidianPath();
  }, []);

  // ============================================================
  // TELEGRAM STATUS
  // ============================================================

  useEffect(() => {
    const loadTelegramStatus = async () => {
      setTelegramLoading(true);
      setTelegramError(null);

      try {
        const response = await fetch("/api/telegram/status", {
          credentials: "include",
        });

        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }

        const data = await response.json();

        setTelegramLinked(Boolean(data.linked));
        setTelegramId(data.telegram_id ?? null);
        setTelegramLinkedAt(data.linked_at ?? null);
      } catch (err) {
        console.error("Failed to load Telegram status:", err);
        setTelegramError(
          "Не удалось проверить статус подключения Telegram"
        );
      } finally {
        setTelegramLoading(false);
      }
    };

    loadTelegramStatus();
  }, []);

  // ============================================================
  // GOOGLE CONNECT
  // ============================================================

  const handleGoogleConnect = async () => {
    setLoading(true);
    setError(null);

    try {
      window.location.href = "/api/google/auth";
    } catch (err) {
      console.error("Failed to initiate Google connection:", err);
      setError("Не удалось инициализировать подключение к Google");
      setLoading(false);
    }
  };

  // ============================================================
  // GOOGLE DISCONNECT
  // ============================================================

  const handleGoogleDisconnect = async () => {
    setLoading(true);
    setError(null);

    try {
      const response = await fetch("/api/google/disconnect", {
        method: "POST",
        credentials: "include",
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const data = await response.json();

      if (data.success) {
        setGoogleConnected(false);

        localStorage.setItem(
          "googleConnected",
          JSON.stringify(false)
        );
      } else {
        throw new Error(data.message || "Unknown error");
      }
    } catch (err) {
      console.error("Failed to disconnect Google:", err);
      setError("Не удалось отключить аккаунт Google");
    } finally {
      setLoading(false);
    }
  };

  // ============================================================
  // GOOGLE CALENDAR SELECT
  // ============================================================

  const handleCalendarSelect = (calendarId) => {
    setSelectedCalendar(calendarId);
    setCalendarSuccess(false);
  };

  const handleCalendarSave = async () => {
    setCalendarLoading(true);
    setCalendarError(null);
    setCalendarSuccess(false);

    try {
      const response = await fetch("/api/google/calendar/select", {
        method: "POST",
        credentials: "include",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          calendar_id: selectedCalendar,
        }),
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const data = await response.json();

      if (data.success) {
        setCalendarSuccess(true);
        // Optionally, show a success message
      } else {
        throw new Error(data.message || "Не удалось сохранить выбор календаря");
      }
    } catch (err) {
      console.error("Failed to save Google calendar selection:", err);
      setCalendarError(err.message || "Не удалось сохранить выбор календаря");
    } finally {
      setCalendarLoading(false);
    }
  };

  // ============================================================
  // TELEGRAM GENERATE LINK CODE
  // ============================================================

  const handleTelegramLink = async () => {
    setTelegramLoading(true);
    setTelegramError(null);
    setTelegramMessage(null);

    try {
      const response = await fetch("/api/telegram/link", {
        method: "POST",
        credentials: "include",
      });

      const data = await response.json().catch(() => null);

      if (!response.ok) {
        throw new Error(
          data?.detail || `HTTP error! status: ${response.status}`
        );
      }

      setTelegramCode(data.code || "");
      setTelegramCodeExpiresAt(data.expires_at || null);
      setTelegramMessage(
        "Код создан. Отправьте его нашему Telegram-боту."
      );
    } catch (err) {
      console.error("Failed to generate Telegram link code:", err);

      setTelegramError(
        err.message || "Не удалось создать код привязки Telegram"
      );
    } finally {
      setTelegramLoading(false);
    }
  };

  // ============================================================
  // TELEGRAM STATUS REFRESH
  // ============================================================

  const handleTelegramRefresh = async () => {
    setTelegramLoading(true);
    setTelegramError(null);

    try {
      const response = await fetch("/api/telegram/status", {
        credentials: "include",
      });

      const data = await response.json().catch(() => null);

      if (!response.ok) {
        throw new Error(
          data?.detail || `HTTP error! status: ${response.status}`
        );
      }

      setTelegramLinked(Boolean(data.linked));
      setTelegramId(data.telegram_id ?? null);
      setTelegramLinkedAt(data.linked_at ?? null);

      if (data.linked) {
        setTelegramCode("");
        setTelegramCodeExpiresAt(null);

        setTelegramMessage(
          "Telegram успешно подключён."
        );
      }
    } catch (err) {
      console.error("Failed to refresh Telegram status:", err);

      setTelegramError(
        "Не удалось обновить статус Telegram"
      );
    } finally {
      setTelegramLoading(false);
    }
  };

  // ============================================================
  // TELEGRAM UNLINK
  // ============================================================

  const handleTelegramUnlink = async () => {
    setTelegramLoading(true);
    setTelegramError(null);
    setTelegramMessage(null);

    try {
      const response = await fetch("/api/telegram/unlink", {
        method: "POST",
        credentials: "include",
      });

      const data = await response.json().catch(() => null);

      if (!response.ok) {
        throw new Error(
          data?.detail || `HTTP error! status: ${response.status}`
        );
      }

      if (!data.success) {
        throw new Error(
          data.message || "Не удалось отвязать Telegram"
        );
      }

      setTelegramLinked(false);
      setTelegramId(null);
      setTelegramLinkedAt(null);
      setTelegramCode("");
      setTelegramCodeExpiresAt(null);

      setTelegramMessage(
        "Telegram успешно отвязан."
      );
    } catch (err) {
      console.error("Failed to unlink Telegram:", err);

      setTelegramError(
        err.message || "Не удалось отвязать Telegram"
      );
    } finally {
      setTelegramLoading(false);
    }
  };

  // ============================================================
  // COPY TELEGRAM CODE
  // ============================================================

  const handleCopyTelegramCode = async () => {
    if (!telegramCode) {
      return;
    }

    try {
      await navigator.clipboard.writeText(telegramCode);
      setTelegramMessage("Код скопирован в буфер обмена.");
    } catch (err) {
      console.error("Failed to copy Telegram code:", err);

      setTelegramMessage(
        "Не удалось автоматически скопировать код."
      );
    }
  };

  // ============================================================
  // OBSIDIAN SAVE
  // ============================================================

  const handleObsidianSave = async (e) => {
    e.preventDefault();

    const path = e.target.elements.obsidianPath.value.trim();

    if (!path) {
      alert("Пожалуйста, укажите путь к папке Обсидиан");
      return;
    }

    try {
      const response = await fetch("/api/obsidian/path", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        credentials: "include",
        body: JSON.stringify({
          vault: path,
        }),
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const data = await response.json();

      setObsidianPath(data.path);

      localStorage.setItem(
        "obsidianPath",
        data.path
      );

      alert(`Obsidian path saved: ${data.path}`);
    } catch (err) {
      console.error("Failed to save Obsidian path:", err);

      alert(
        "Не удалось сохранить путь к Обсидиан. Пожалуйста, попробуйте снова."
      );
    }
  };

  // ============================================================
  // RENDER
  // ============================================================

  return (
    <div className="min-h-[calc(100vh-4rem)] bg-background p-6 space-y-6">
      <div className="flex items-center justify-between mb-4">
        <h2 className="text-2xl font-bold text-primary tracking-tighter">
          Настройки
        </h2>
        <div className="flex items-center space-x-3">
          <button
            onClick={handleGoogleConnect}
            disabled={loading || !googleConnected}
            className="px-4 py-2 bg-accentBlue/20 hover:bg-accentBlue/30 text-primary rounded-lg transition-all duration-200 hover:shadow-glow-blue"
          >
            {loading ? "Подключение..." : "Подключить Google"}
          </button>
        </div>
      </div>

      {/* ======================================================
          GOOGLE ACCOUNT
      ======================================================= */}
      <div className="bg-panel/80 backdrop-blur-sm rounded-2xl border border-border/50 p-6">
        <div className="space-y-4">
          <div className="flex items-center mb-2">
            <div className="w-8 h-8 bg-accentYellow/20 rounded-xl flex items-center justify-center mr-3">
              <span className="text-accentYellow text-xl">🔐</span>
            </div>
            <h3 className="font-semibold text-accentYellow">
              Google аккаунт
            </h3>
          </div>

          <p className="text-sm text-secondary">
            Подвяжите свой Google аккаунт для синхронизации
            календаря и других сервисов.
          </p>

          {loading ? (
            <div className="flex items-center space-x-3">
              <div className="w-4 h-4 border-2 border-accentYellow border-t-transparent rounded-full animate-spin" />
              <span className="text-accentYellow">Проверка подключения...</span>
            </div>
          ) : error ? (
            <div className="flex items-center space-x-3">
              <div className="w-4 h-4 bg-accentRed/20 rounded flex items-center justify-center">
                <span className="text-accentRed">❌</span>
              </div>
              <span className="text-accentRed">{error}</span>
            </div>
          ) : googleConnected ? (
            <div className="flex items-center space-x-3">
              <div className="w-4 h-4 bg-accentGreen/20 rounded flex items-center justify-center">
                <span className="text-accentGreen">✅</span>
              </div>
              <span className="text-accentGreen">✅ Подключён</span>

              <button
                onClick={handleGoogleDisconnect}
                className="ml-4 px-3 py-1.5 bg-accentRed/20 hover:bg-accentRed/30 text-accentRed rounded transition-all duration-200 hover:shadow-glow-red"
              >
                Отключить
              </button>
            </div>
          ) : (
            <button
              onClick={handleGoogleConnect}
              className="px-5 py-2.5 bg-accentBlue/20 hover:bg-accentBlue/30 text-primary rounded-lg w-full transition-all duration-200 hover:shadow-glow-blue"
            >
              Подключить Google аккаунт
            </button>
          )}
        </div>
      </div>

      {/* ======================================================
          GOOGLE CALENDAR SELECTION
      ======================================================= */}
      {googleConnected && (
        <div className="bg-panel/80 backdrop-blur-sm rounded-2xl border border-border/50 p-6">
          <div className="space-y-4">
            <div className="flex items-center mb-2">
              <div className="w-8 h-8 bg-accentYellow/20 rounded-xl flex items-center justify-center mr-3">
                <span className="text-accentYellow text-xl">📅</span>
              </div>
              <h3 className="font-semibold text-accentYellow">
                Выбор календаря Google
              </h3>
            </div>

            <p className="text-sm text-secondary">
              Выберите календарь для синхронизации с вашим расписанием МАИ.
            </p>

            {calendarLoading ? (
              <div className="flex items-center space-x-3">
                <div className="w-4 h-4 border-2 border-accentYellow border-t-transparent rounded-full animate-spin" />
                <span className="text-accentYellow">Загрузка календарей...</span>
              </div>
            ) : calendarError ? (
              <div className="space-y-3">
                <div className="flex items-center space-x-3 mb-2">
                  <div className="w-4 h-4 bg-accentRed/20 rounded flex items-center justify-center">
                    <span className="text-accentRed">❌</span>
                  </div>
                  <span className="text-accentRed">{calendarError}</span>
                </div>
                <button
                  onClick={() => {
                    setCalendarLoading(true);
                    setCalendarError(null);
                    // Trigger refetch
                  }}
                  className="px-3 py-1.5 bg-accentBlue/20 hover:bg-accentBlue/30 text-primary rounded transition-all duration-200"
                >
                  Повторить
                </button>
              </div>
            ) : calendarSuccess ? (
              <div className="flex items-center space-x-3">
                <div className="w-4 h-4 bg-accentGreen/20 rounded flex items-center justify-center">
                  <span className="text-accentGreen">✅</span>
                </div>
                <span className="text-accentGreen">Выбор календаря сохранён!</span>
              </div>
            ) : (
              <>
                <div className="mb-4">
                  <label className="block text-sm font-medium text-primary mb-2">
                    Календари
                  </label>
                  <div className="border border-border rounded-md max-h-[300px] overflow-y-auto">
                    {calendars.length === 0 ? (
                      <div className="py-4 text-center text-gray-500">
                        Календари не найдены
                      </div>
                    ) : (
                      <ul className="divide-y divide-border/50">
                        {/* Option to select no calendar */}
                        <li
                          key="none"
                          className={`px-4 py-3 hover:bg-gray-50 cursor-pointer ${selectedCalendar === null ? "bg-accentBlue/20" : ""
                            }`}
                          onClick={() => handleCalendarSelect(null)}
                        >
                          <div className="flex justify-between text-sm">
                            <div>
                              <p className="font-medium text-primary">Не выбран</p>
                              <p className="text-xs text-gray-500">Синхронизация отключена</p>
                            </div>
                            {selectedCalendar === null && (
                              <span className="text-accentGreen">✓ Выбрано</span>
                            )}
                          </div>
                        </li>

                        {calendars.map((calendar) => (
                          <li
                            key={calendar.id}
                            className={`px-4 py-3 hover:bg-gray-50 cursor-pointer ${selectedCalendar === calendar.id ? "bg-accentBlue/20" : ""
                              }`}
                            onClick={() => handleCalendarSelect(calendar.id)}
                          >
                            <div className="flex justify-between text-sm">
                              <div>
                                <p className="font-medium text-primary">{calendar.summary}</p>
                                {calendar.id !== "primary" && (
                                  <p className="text-xs text-gray-500">ID: {calendar.id}</p>
                                )}
                              </div>
                              {selectedCalendar === calendar.id && (
                                <span className="text-accentGreen">✓ Выбрано</span>
                              )}
                            </div>
                          </li>
                        ))}
                      </ul>
                    )}
                  </div>
                </div>

                <div className="mt-4">
                  <button
                    onClick={handleCalendarSave}
                    disabled={calendarLoading}
                    className="w-full px-5 py-3 bg-accentBlue text-white rounded-xl hover:bg-accentBlue/90 transition-all duration-200 disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                    {calendarLoading ? "Сохранение..." : "Сохранить выбор"}
                  </button>
                </div>
              </>
            )}
          </div>
        </div>
      )}

      {/* ======================================================
          TELEGRAM
      ======================================================= */}
      <div className="bg-panel/80 backdrop-blur-sm rounded-2xl border border-border/50 p-6">
        <div className="space-y-4">
          <div className="flex items-center mb-2">
            <div className="w-8 h-8 bg-accentYellow/20 rounded-xl flex items-center justify-center mr-3">
              <span className="text-accentYellow text-xl">💬</span>
            </div>
            <h3 className="font-semibold text-accentYellow">
              Telegram
            </h3>
          </div>

          <p className="text-sm text-secondary">
            Подключите Telegram, чтобы использовать бота XO_OS
            как дополнительный интерфейс управления системой.
          </p>

          {telegramLoading ? (
            <div className="text-accentYellow">
              Проверка подключения...
            </div>
          ) : telegramError ? (
            <div className="space-y-3">
              <div className="flex items-center space-x-3">
                <div className="w-4 h-4 bg-accentRed/20 rounded flex items-center justify-center">
                  <span className="text-accentRed">❌</span>
                </div>
                <span className="text-accentRed">{telegramError}</span>
              </div>

              <button
                onClick={handleTelegramRefresh}
                className="px-3 py-1.5 bg-accentBlue/20 hover:bg-accentBlue/30 text-primary rounded transition-all duration-200"
              >
                Повторить
              </button>
            </div>
          ) : telegramLinked ? (
            <div className="space-y-4">
              <div className="flex items-center space-x-3">
                <div className="w-4 h-4 bg-accentGreen/20 rounded flex items-center justify-center">
                  <span className="text-accentGreen">✅</span>
                </div>
                <span className="text-accentGreen">Telegram подключён</span>
              </div>

              {telegramId && (
                <div className="text-sm text-secondary">
                  Telegram ID: {telegramId}
                </div>
              )}

              {telegramLinkedAt && (
                <div className="text-sm text-secondary">
                  Подключён:{" "}
                  {new Date(telegramLinkedAt).toLocaleString("ru-RU")}
                </div>
              )}

              <div className="flex flex-wrap gap-3 mt-3">
                <button
                  onClick={handleTelegramRefresh}
                  className="px-4 py-2 bg-accentBlue/20 hover:bg-accentBlue/30 text-primary rounded transition-all duration-200"
                >
                  Обновить статус
                </button>

                <button
                  onClick={handleTelegramUnlink}
                  className="px-4 py-2 bg-accentRed/20 hover:bg-accentRed/30 text-primary rounded transition-all duration-200"
                >
                  Отвязать Telegram
                </button>
              </div>
            </div>
          ) : (
            <div className="space-y-4">
              <button
                onClick={handleTelegramLink}
                className="w-full px-5 py-3 bg-accentBlue/20 hover:bg-accentBlue/30 text-primary rounded-lg transition-all duration-200 hover:shadow-glow-blue"
              >
                Привязать Telegram
              </button>

              {telegramCode && (
                <div className="mt-4 p-4 bg-background/50 border border-border rounded-xl">
                  <div className="text-sm text-secondary mb-2">
                    Ваш одноразовый код привязки:
                  </div>

                  <div className="flex items-center space-x-3 mb-3">
                    <code className="px-4 py-2 bg-panel border border-border rounded-lg text-lg tracking-widest text-primary font-mono">
                      {telegramCode}
                    </code>

                    <button
                      onClick={handleCopyTelegramCode}
                      className="px-3 py-2 bg-accentBlue/20 hover:bg-accentBlue/30 text-primary rounded transition-all duration-200"
                    >
                      Копировать
                    </button>
                  </div>

                  {telegramCodeExpiresAt && (
                    <div className="text-xs text-secondary">
                      Код действует до:{" "}
                      {new Date(telegramCodeExpiresAt).toLocaleTimeString("ru-RU")}
                    </div>
                  )}

                  <div className="text-sm text-secondary">
                    Отправьте этот код нашему Telegram-боту вручную — или нажмите
                    кнопку ниже, бот получит код автоматически.
                  </div>

                  <div className="flex items-center space-x-3 mt-3">
                    <a
                      href={`https://t.me/XO_OS_bot?start=${telegramCode}`}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="px-4 py-2 bg-accentBlue/20 hover:bg-accentBlue/30 text-primary rounded transition-all duration-200 hover:shadow-glow-blue"
                    >
                      Открыть бота и привязать
                    </a>

                    <button
                      onClick={handleTelegramRefresh}
                      className="px-4 py-2 bg-accentBlue/20 hover:bg-accentBlue/30 text-primary rounded transition-all duration-200"
                    >
                      Обновить статус
                    </button>
                  </div>
                </div>
              )}

              {telegramMessage && (
                <div className="mt-3 text-sm text-accentGreen">
                  {telegramMessage}
                </div>
              )}
            </div>
          )}

          {!telegramLinked && telegramMessage && !telegramCode && (
            <div className="mt-3 text-sm text-accentGreen">
              {telegramMessage}
            </div>
          )}
        </div>
      </div>

      {/* ======================================================
          OBSIDIAN INTEGRATION
      ======================================================= */}
      <div className="bg-panel/80 backdrop-blur-sm rounded-2xl border border-border/50 p-6">
        <div className="space-y-4">
          <div className="flex items-center mb-2">
            <div className="w-8 h-8 bg-accentYellow/20 rounded-xl flex items-center justify-center mr-3">
              <span className="text-accentYellow text-xl">📓</span>
            </div>
            <h3 className="font-semibold text-accentYellow">
              Обсидиан интеграция
            </h3>
          </div>

          <p className="text-sm text-secondary">
            Укажите путь к вашей папке Обсидиан для
            импорта/экспорта заметок.
          </p>

          <form
            onSubmit={handleObsidianSave}
            className="space-y-3"
          >
            <div>
              <label className="block text-xs text-secondary mb-1">
                Путь к папке Обсидиан
              </label>

              <input
                type="text"
                name="obsidianPath"
                defaultValue={obsidianPath}
                className="w-full px-4 py-3 bg-background border border-border rounded-xl text-primary focus:outline-none focus:ring-2 focus:ring-accentBlue focus:ring-offset-0"
                placeholder="/Users/yourname/Vaults/MyKnowledge"
              />
            </div>

            <button
              type="submit"
              className="w-full px-5 py-3 bg-accentBlue/20 hover:bg-accentBlue/30 text-primary rounded-lg transition-all duration-200 hover:shadow-glow-blue"
            >
              Сохранить путь
            </button>
          </form>

          {obsidianPath && (
            <p className="mt-2 text-xs text-accentGreen">
              Текущий путь: {obsidianPath}
            </p>
          )}
        </div>
      </div>

      {/* ======================================================
          OTHER SETTINGS
      ======================================================= */}
      <div className="bg-panel/80 backdrop-blur-sm rounded-2xl border border-border/50 p-6">
        <div className="space-y-4">
          <div className="flex items-center mb-2">
            <div className="w-8 h-8 bg-accentYellow/20 rounded-xl flex items-center justify-center mr-3">
              <span className="text-accentYellow text-xl">⚙️</span>
            </div>
            <h3 className="font-semibold text-accentYellow">
              Другие настройки
            </h3>
          </div>

          <p className="text-sm text-secondary">
            Здесь можно добавить дополнительные настройки
            приложения.
          </p>
        </div>
      </div>
    </div>
  );
};

export default Settings;